import * as T from'three';
const Q=t=>(t=T.MathUtils.clamp(t,0,1))*t*t*(10-15*t+6*t*t);
class Prelude extends T.Curve{
 constructor(A,mean,d,s){super();Object.assign(this,{A,mean,d,s});this.arcLengthDivisions=1024;this.L=super.getLength();}
 getPoint(t,out=new T.Vector3()){const q=Q(t),a=Math.PI/2*q;return out.copy(this.mean).add(new T.Vector3(-this.s.sourceRunMM*t,this.d*Math.cos(a),this.s.sourceLiftMM*q+this.d*Math.sin(a))).addScaledVector(this.A.clone().sub(this.mean).add(new T.Vector3(0,-this.d,0)),1-q);}
 getTangent(t,out=new T.Vector3()){if(t===0)return out.set(-1,0,0);if(t===1)return out.set(-1,0,0);return super.getTangent(t,out);}getLength(){return this.L??super.getLength();}
}
class Quarter extends T.Curve{
 constructor(mode,C,r){super();Object.assign(this,{mode,C,r});this.L=r*Math.PI/2;}
 getPoint(t,out=new T.Vector3()){const a=t*Math.PI/2,c=this.C,r=this.r;if(this.mode==='source')return out.set(c.x-r*Math.sin(a),c.y,c.z-r*Math.cos(a));if(this.mode==='up')return out.set(c.x,c.y-r*Math.cos(a),c.z+r*Math.sin(a));return out.set(c.x,c.y+r*Math.sin(a),c.z+r*Math.cos(a));}
 getPointAt(t,out){return this.getPoint(t,out);}getTangent(t,out=new T.Vector3()){const a=t*Math.PI/2;if(this.mode==='source')return out.set(-Math.cos(a),0,Math.sin(a));if(this.mode==='up')return out.set(0,Math.sin(a),Math.cos(a));return out.set(0,Math.cos(a),-Math.sin(a));}getTangentAt(t,out){return this.getTangent(t,out);}getLength(){return this.L;}
}
class Fanout extends T.Curve{
 constructor(A,B){super();Object.assign(this,{A,B});this.arcLengthDivisions=1024;this.L=super.getLength();}
 getPoint(t,out=new T.Vector3()){return out.set(T.MathUtils.lerp(this.A.x,this.B.x,Q(t)),this.A.y,T.MathUtils.lerp(this.A.z,this.B.z,t));}getTangent(t,out=new T.Vector3()){if(t===0||t===1)return out.set(0,0,1);return super.getTangent(t,out);}getLength(){return this.L??super.getLength();}
}
export const MOTOR_DUCT={sourceRunMM:10,sourceLiftMM:1,sourceBendRadiusMM:2.5,fanoutDelayMM:1,fanoutRiseMM:8,upperBendRadiusMM:2};
export class MotorDuctCurve extends T.Curve{
 constructor(A,mean,d,stock,frame,slot,s=MOTOR_DUCT){super();Object.assign(this,{stockMM:stock,entryMM:3.75});const end=new T.Vector3(slot,2.75,1.25).applyMatrix4(frame),B=new T.Vector3(slot,-1,1.25).applyMatrix4(frame),axis=new T.Vector3(0,1,0).transformDirection(frame);if(!axis.equals(new T.Vector3(0,0,-1)))throw Error('Motor duct reference requires the actual J4 insertion frame');this.end=end;this.entryStart=B;const pre=new Prelude(A,mean,d,s),r0=s.sourceBendRadiusMM-d,R=s.upperBendRadiusMM;if(!(r0>.26))throw Error('Full motor OD needs a larger source turn');const C=new T.Vector3(mean.x-s.sourceRunMM,mean.y,mean.z+s.sourceLiftMM+s.sourceBendRadiusMM),arc=new Quarter('source',C,r0),P=arc.getPointAt(1),F0=P.clone().add(new T.Vector3(0,0,s.fanoutDelayMM)),F1=new T.Vector3(B.x,mean.y,F0.z+s.fanoutRiseMM),fanout=new Fanout(F0,F1),dy=B.y-mean.y;if(!(dy>2*R))throw Error('Actual J4 source-to-entry lane too narrow for the retained reference turns');
 const nonHeight=pre.getLength()+arc.getLength()+s.fanoutDelayMM+fanout.getLength()+Math.PI*R+dy-2*R+this.entryMM,H=(stock-nonHeight+2*R+F1.z+B.z)/2;if(!(H-R>F1.z&&H-R>B.z))throw Error('Full motor stock cannot reach this actual pose with the complete duct reference');
 const A0=new T.Vector3(B.x,mean.y,H-R),up=new Quarter('up',new T.Vector3(B.x,mean.y+R,H-R),R),A1=up.getPointAt(1),C0=new T.Vector3(B.x,B.y-R,H),down=new Quarter('down',new T.Vector3(B.x,B.y-R,H-R),R),D0=down.getPointAt(1),line=(A,B)=>new T.LineCurve3(A,B);this.parts=[pre,arc,line(P,F0),fanout,line(F1,A0),up,line(A1,C0),down,line(D0,B),line(B,end)];this.lengths=this.parts.map(c=>c.getLength());this.measuredMM=this.lengths.reduce((a,b)=>a+b,0);this.prefixMM=pre.getLength();this.bankStockMM=stock-this.prefixMM-this.entryMM;this.bank={mode:'analytic-source-duct-bight',a:H,h:R,D:new T.Vector3(0,0,1),measuredMM:this.measuredMM-this.prefixMM-this.entryMM,coefficientUnits:'mm'};this.sourceTurnRadiusMM=r0;this.upperTurnRadiusMM=R;this.referenceParameters=s;
 }
 getLength(){return this.stockMM;}locate(u){if(u<=0)return[this.parts[0],0];if(u>=1)return[this.parts.at(-1),1];let s=u*this.stockMM;for(let i=0;i<this.parts.length;i++){if(s<=this.lengths[i]||i===this.parts.length-1)return[this.parts[i],T.MathUtils.clamp(s/this.lengths[i],0,1)];s-=this.lengths[i];}}
 getPointAt(u,out){const[p,t]=this.locate(T.MathUtils.clamp(u,0,1));return p.getPointAt(t,out);}getPoint(u,out){return this.getPointAt(u,out);}getTangentAt(u,out){const[p,t]=this.locate(T.MathUtils.clamp(u,0,1));return p.getTangentAt(t,out);}getTangent(u,out){return this.getTangentAt(u,out);}
 materialGrid(length,N){const lengths=[];let remain=length;for(const L of this.lengths){if(remain<=0)break;lengths.push(Math.min(L,remain));remain-=L;}const minimum=[8,8,2,8,2,8,2,8,2,1].slice(0,lengths.length),extra=N-minimum.reduce((a,b)=>a+b,0);if(extra<0)throw Error('Complete motor section sampling budget unavailable');const raw=lengths.map(L=>extra*L/length),counts=minimum.map((n,i)=>n+Math.floor(raw[i]));let rest=N-counts.reduce((a,b)=>a+b,0);for(const i of raw.map((x,i)=>({i,f:x-Math.floor(x)})).sort((a,b)=>b.f-a.f||a.i-b.i).map(q=>q.i)){if(!rest)break;counts[i]++;rest--;}const grid=[0];let at=0;for(let i=0;i<lengths.length;i++){for(let k=1;k<=counts[i];k++)grid.push(at+lengths[i]*k/counts[i]);at+=lengths[i];}grid[N]=length;return grid;}
}
export function createMotorDuctCurves(sources,stocks,frame,slots,settings=MOTOR_DUCT){const A=sources.map(c=>c.getPointAt(0)),mean=A.reduce((p,q)=>p.add(q),new T.Vector3()).multiplyScalar(1/A.length);return A.map((p,i)=>new MotorDuctCurve(p,mean,p.y-mean.y,stocks[i],frame,slots[i],settings));}
